  import React from 'react'
  import { MDXTag } from '@mdx-js/tag'
  import { Playground, PropsTable } from 'docz'
import { Blurb } from '../src/index'

const layoutProps = {

};
export default class MDXContent extends React.Component {
  constructor(props) {
    super(props)
    this.layout = null
  }
  render() {
    const { components, ...props } = this.props

    return <MDXTag
             name="wrapper"

             components={components}>
<MDXTag name="h1" components={components} props={{"id":"blurb"}}>{`Blurb`}</MDXTag>
<MDXTag name="p" components={components}>{`The `}<MDXTag name="inlineCode" components={components} parentName="p">{`Blurb`}</MDXTag>{` component doesn't do much, it's sort of similar to the `}<MDXTag name="inlineCode" components={components} parentName="p">{`Card`}</MDXTag>{` component in that it does very little but can help to reduce ad-hoc components. It's likely better to try and extends it's usage rather than to use `}<MDXTag name="inlineCode" components={components} parentName="p">{`Header`}</MDXTag>{` and `}<MDXTag name="inlineCode" components={components} parentName="p">{`Paragraph`}</MDXTag>{` elements directly.`}</MDXTag>
<Playground __codesandbox={`undefined`} __position={0} __code={'<div style={{ maxWidth: \'275px\', margin: \'0 auto\' }}>\n    <Blurb right variant=\"b\" serif header=\"Did you know?\" />\n    <Blurb\n      right\n      variant=\"c\"\n      header=\"97 Members\"\n      body=\"have shopped around in your postcode this week!\"\n    />\n    <Blurb\n      right\n      header=\"264,245 Members\"\n      body=\"From Sydney have switch so far this year!\"\n    />\n  \n</Playground>'} __scope={{props: this ? this.props : props,Blurb}}>
  <div style={{maxWidth: '275px', margin: '0 auto'}}>
      <Blurb right variant="b" serif header="Did you know?" />
      <Blurb right variant="c" header="97 Members" body="have shopped around in your postcode this week!" />
      <Blurb right header="264,245 Members" body="From Sydney have switch so far this year!" />
  </div>
</Playground>
<MDXTag name="h2" components={components} props={{"id":"proptypes"}}>{`PropTypes`}</MDXTag>
<PropsTable of={Blurb} />
           </MDXTag>
  }
}
